// P1 rules — the shared vectors (test/vectors/connect-rules/, generated by
// test/tools/gen-connect-rule-vectors.mjs: payload.json from
// src/connect/ui/actions.js (P1b), rules.json from src/connect/ui/text.js and
// src/connect/core.js acceptanceMayAutoApprove (P1a);
// design docs/plans/2026-10-12-connect-core-p1-rules-design.md rev 2 §2).
// Every .json file of the directory is read: rules.json joins with no
// change here.
//
// What it proves:
//   - always: every vector's "expect" is STILL what today's JavaScript
//     returns for its "args", through the argument contract and result
//     encoding of connect/nc_rules_json.h (jsRule) — a vector file older
//     than the JS fails here instead of freezing a stale expectation;
//   - with NODUS_SEND_PARITY_OUT (`scripts/build-nodus-send-wasm.sh parity`;
//     otherwise SKIP — a skip is not a pass): the parity TEST wasm's
//     nc_rule_test (connect/nc_wasm.c, the same dispatcher native ctest
//     test_nc_rules runs) returns exactly the expected bytes for every
//     vector. The input crosses through the module's heap buffer
//     (nc_rule_in_alloc), not a ccall string.
// A vector marked "gap" (a behaviour the C port knowingly does not
// reproduce — today full-Unicode toLowerCase) is run like every other; a
// mismatch is a failure, reported with its reason.
// Three of rules.json's pendingOutbox vectors pin WHICH error V8's sort throws
// when two seqs are malformed differently (connect/nc_rules.h): another
// engine may throw another class there.
// Requires: the vector file(s) — none is a FAILURE, not a skip.
// Leaves behind: nothing.
// How it can lie: the JS check compares the JS with itself through the
// same harness that wrote the vectors; it proves the file is current, not
// that the harness's contract is the C one — that is the C/wasm half.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { jsRule } from './tools/gen-connect-rule-vectors.mjs';

const DIR = fileURLToPath(new URL('./vectors/connect-rules/', import.meta.url));

function loadVectors() {
  assert.ok(existsSync(DIR), `${DIR} is missing — run node test/tools/gen-connect-rule-vectors.mjs`);
  const files = readdirSync(DIR).filter(f => f.endsWith('.json')).sort();
  assert.ok(files.length > 0, `no vector file in ${DIR}`);
  const all = [];
  for (const f of files) {
    const list = JSON.parse(readFileSync(join(DIR, f), 'utf8'));
    assert.ok(Array.isArray(list) && list.length > 0, `${f}: not a non-empty array`);
    list.forEach((v, i) => {
      assert.ok(typeof v.rule === 'string' && typeof v.args === 'string' && typeof v.expect === 'string', `${f}[${i}]: malformed vector`);
      all.push({ ...v, where: `${f}[${i}] ${v.rule}${v.gap ? ` (gap: ${v.gap})` : ''}` });
    });
  }
  return all;
}

test('connect rules: every vector is what today\'s JavaScript returns', () => {
  const vectors = loadVectors();
  for (const v of vectors) assert.equal(jsRule(v.rule, v.args), v.expect, `${v.where}\n  args: ${v.args}`);
});

const PARITY_OUT = process.env.NODUS_SEND_PARITY_OUT;
const skip = !PARITY_OUT ? 'set NODUS_SEND_PARITY_OUT (build-nodus-send-wasm.sh parity)' : false;

test('connect rules: the parity wasm (nc_rule_test) returns every vector\'s bytes', { skip }, async () => {
  const path = join(PARITY_OUT, 'send-test-node.mjs');
  assert.ok(existsSync(path), `${path} is missing — run build-nodus-send-wasm.sh parity`);
  const { default: create } = await import(pathToFileURL(path).href);
  const M = await create();
  const vectors = loadVectors();
  const failures = [];
  for (const v of vectors) {
    const input = Buffer.from(v.args, 'utf8');
    const at = M.ccall('nc_rule_in_alloc', 'number', ['number'], [input.length]);
    assert.ok(at, `${v.where}: nc_rule_in_alloc(${input.length}) failed`);
    M.HEAPU8.set(input, at);
    const out = M.ccall('nc_rule_test', 'number', ['string'], [v.rule]);
    assert.ok(out, `${v.where}: nc_rule_test returned NULL (out of memory)`);
    const heap = M.HEAPU8;                      // re-read: memory may have grown
    let end = out;
    while (heap[end] !== 0) end++;
    const got = Buffer.from(heap.subarray(out, end));
    if (!got.equals(Buffer.from(v.expect, 'utf8')))
      failures.push(`${v.where}\n  args:   ${v.args}\n  got:    ${got.toString('utf8')}\n  expect: ${v.expect}`);
  }
  assert.equal(failures.length, 0, `${failures.length} of ${vectors.length} vectors differ:\n${failures.join('\n')}`);
});
